import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Cv-B11KK.js";const b=JSON.parse('{"title":"About bbtex","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1790322248000}'),r={name:"about.md"};function n(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="about-bbtex" tabindex="-1">About bbtex <a class="header-anchor" href="#about-bbtex" aria-label="Permalink to &quot;About bbtex&quot;">​</a></h1><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>I write my papers in BBEdit. It&#39;s a great editor, but for LaTeX I kept missing what other editors have: LaTeXTools in Sublime, AUCTeX in Emacs. One key to build, errors you can click, a PDF that follows the cursor, equations you can check without recompiling forty pages.</p><p>bbtex brings those things to BBEdit while staying out of the way. It uses BBEdit&#39;s own Scripts menu, results browser and preview windows, so it should feel like part of the editor rather than a plugin bolted on.</p><h2 id="totally-vibe-coded" tabindex="-1">Totally vibe coded <a class="header-anchor" href="#totally-vibe-coded" aria-label="Permalink to &quot;Totally vibe coded&quot;">​</a></h2><p>bbtex is <strong>vibe coded, top to bottom</strong>. I didn&#39;t write the code. An AI coding agent (<a href="https://claude.com/claude-code" target="_blank" rel="noreferrer">Claude Code</a>) wrote all of it: the OCaml, the bash and AppleScript glue, the tests, and the docs you&#39;re reading. My part was deciding what it should do, trying it in BBEdit, and pushing back when something felt wrong.</p><p>To keep that honest, the project leans on process:</p><ul><li><strong>House rules for the agent.</strong> <a href="https://github.com/LouLouLibs/bbtex/blob/main/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> says what goes where: logic in the OCaml binary, only thin glue in bash, no shipped Python, and how to test.</li><li><strong>Lots of tests.</strong> Unit and cram tests, a local CI script, real-engine runs with pdfLaTeX, XeLaTeX, LuaLaTeX and Tectonic (with BibTeX and Biber), and native tests that drive a real BBEdit window.</li><li><strong>Reviews.</strong> Bigger features go through a written plan, a review of each step, and a final review of the whole branch before they&#39;re merged.</li></ul><p>That still doesn&#39;t make it bulletproof. Keep your papers in version control, and if bbtex does something surprising, please <a href="https://github.com/LouLouLibs/bbtex/issues" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="where-things-stand-v0-1-0" tabindex="-1">Where things stand: v0.1.0 <a class="header-anchor" href="#where-things-stand-v0-1-0" aria-label="Permalink to &quot;Where things stand: v0.1.0&quot;">​</a></h2><p>This is the first release. What I&#39;d call solid:</p><ul><li>builds with latexmk and Tectonic, with errors in the results browser</li><li>SyncTeX with Skim in both directions</li><li>equation previews, including refresh on save and live selection</li><li>the project outline, and the citation and reference pickers</li><li>environment editing, the clippings, and Doctor</li></ul><p>What to know before you try it:</p><ul><li>It&#39;s tested on Apple Silicon only, on the macOS version I run. Intel builds aren&#39;t checked.</li><li>A clean install on a brand-new Mac account hasn&#39;t been walked through yet. If you&#39;re the first, <a href="./setup-troubleshooting#fresh-account-or-fresh-mac-acceptance">the checklist</a> is there, and I&#39;d love to hear how it went.</li><li>Previews read your <strong>saved</strong> preamble; unsaved edits in other files aren&#39;t picked up yet.</li><li>The RaTeX engine option is an experimental placeholder. Stick with pdfLaTeX, XeLaTeX, LuaLaTeX or Tectonic.</li></ul><p>The <a href="./changelog">release notes</a> have the details, and <a href="./editor-comparison">how it compares</a> lists what TeXShop, LaTeXTools and AUCTeX still do better.</p><h2 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h2><p>bbtex stands on other people&#39;s work:</p><ul><li>The editing clippings and stationery come from the old <strong>Latex.bbpackage</strong> (<a href="https://github.com/LouLouLibs/bbtex/blob/main/support/THIRD-PARTY-NOTICES.md" target="_blank" rel="noreferrer">notices</a>).</li><li><a href="https://github.com/latex-lsp/texlab" target="_blank" rel="noreferrer">TexLab</a> provides completion and navigation through BBEdit&#39;s language-server support.</li><li>Equation previews crop with AUCTeX&#39;s <code>preview.sty</code> and convert with Poppler.</li><li>Citation search uses <a href="https://github.com/LouLouLibs/bibtexparser-ml" target="_blank" rel="noreferrer">bibtexparser-ml</a>, an OCaml port of python-bibtexparser&#39;s splitter (vibe coded too).</li><li><a href="https://skim-app.sourceforge.io/" target="_blank" rel="noreferrer">Skim</a> makes SyncTeX on the Mac pleasant.</li></ul><p>bbtex is part of <a href="https://github.com/LouLouLibs" target="_blank" rel="noreferrer">LouLouLibs</a> and is MIT licensed.</p>',19)])])}const u=t(r,[["render",n]]);export{b as __pageData,u as default};
